#include <iostream>
#include <mutex>
#include <thread>
#include <vector>
struct SafeCounter {
  std::mutex m; long v = 0;
  void increment() { std::lock_guard<std::mutex> lk(m); ++v; }
  long get() { std::lock_guard<std::mutex> lk(m); return v; }
};
int main() {
  SafeCounter c;
  std::vector<std::thread> ts;
  for(int i=0;i<4;++i) ts.emplace_back([&]{ for(int k=0;k<2500;++k) c.increment(); });
  for(auto&t:ts) t.join();
  std::cout << c.get();
}

// 思路：用两个 atomic<bool> 标志或 condition_variable 做「门闩」：
